steps.run:
echo "A feature description was added to the ./.features/ directory."
make features-validate \
  || { echo "New ./.features/*.md file failed validation."; exit 1; }

python3 -I - renovate.json <<'EOF'
import json, sys
def hook(pairs):
    seen = set()
    for k, _ in pairs:
        if k in seen:
            sys.exit(f"duplicate key {k!r} in {sys.argv[1]}")
        seen.add(k)
    return dict(pairs)
json.load(open(sys.argv[1]), object_pairs_hook=hook)
EOF
